//! Live authoritative recharge. Native source layout/colors/angle/LineStrip.
//! Explicit full-viewport offscreen line layer; original projection/gamma remains open.
use bevy::{prelude::*,asset::RenderAssetUsages,camera::{RenderTarget,visibility::RenderLayers},core_pipeline::tonemapping::Tonemapping,render::render_resource::{Extent3d,TextureDimension,TextureFormat,TextureUsages},sprite_render::Material2dPlugin,ui_render::{UiMaterialPlugin,ui_material::MaterialNode},window::PrimaryWindow};
use crate::{native_hud_element_storage::ElementStorage,native_zip_provider::StartupHud,native_hud_recharge_material::{RechargeMaterial,Parameters},native_hud_recharge_line::{self,LineMaterial}};
struct Slot {sector:Entity,line:Entity,sector_material:Handle<RechargeMaterial>,line_material:Handle<LineMaterial>,mesh:Handle<Mesh>}
#[derive(Resource,Default)] struct Live {sources:Vec<ElementStorage>,slots:Vec<Slot>,camera:Option<Entity>,overlay:Option<Entity>,target:Option<Handle<Image>>,overlay_material:Option<Handle<crate::native_hud_icon_material::IconMaterial>>,signature:Option<String>,error:Option<String>}
pub struct Plugin;
impl bevy::app::Plugin for Plugin {fn build(&self,app:&mut App) {app.add_plugins((UiMaterialPlugin::<RechargeMaterial>::default(),Material2dPlugin::<LineMaterial>::default())).init_resource::<Live>().add_systems(Startup,setup).add_systems(Update,update.after(crate::receive).before(crate::render_probe::capture));}}
fn source(hud:&StartupHud)->Result<Vec<ElementStorage>,String> {
 let mut result=Vec::new();for slot in 0..crate::native_hud_summoners::SLOT_COUNT {let expected=crate::native_hud_summoners::effect_name(slot);let matches:Vec<_>=hud.shadow_isles_layouts.iter().filter(|l|l.request.ends_with(&crate::native_hud_summoners::layout(slot))).flat_map(|l|l.structure.accepted.iter()).filter(|r|r.element.storage.kind()==2 && r.element.storage.bytes()[..32].split(|b|*b==0).next().unwrap()==expected.as_bytes()).collect();
  if matches.len()!=1 {return Err(format!("native recharge {expected} missing or duplicated"));}let s=&matches[0].element.storage;
  if s.flags()&1!=0 || s.word(0x1a4)!=3 {return Err("native recharge initial flags/layer unqualified".into());}let mut copy=ElementStorage::new(2).unwrap();copy.write_bytes(0,s.bytes());result.push(copy);
 }Ok(result)
}
fn rect(s:&ElementStorage,dimensions:[u32;2],scalar:f32)->Result<[f32;4],String> {
 let f=|o|f32::from_bits(s.word(o));crate::native_hud_layout::transform(&crate::native_hud_layout::Input {flags:s.flags(),width:dimensions[0],height:dimensions[1],owner_scalar:scalar,rect:[f(0x1c0),f(0x1c4),f(0x1c8),f(0x1cc)],anchors:[f(0x1a8),f(0x1ac),f(0x1b0),f(0x1b4)],motion_offset:[f(0x1b8),f(0x1bc)],include_motion:false,group_offset:None,fractions:s.initial_fractions(),aspect:f(0x1d8)}).map_err(str::to_owned)
}
fn setup(hud:Res<StartupHud>,mut live:ResMut<Live>) {match source(&hud) {Ok(v)=>live.sources=v,Err(e)=>eprintln!("Native recharge HUD unavailable: {e}")}}
fn remove(live:&mut Live,commands:&mut Commands,images:&mut Assets<Image>,meshes:&mut Assets<Mesh>,sectors:&mut Assets<RechargeMaterial>,lines:&mut Assets<LineMaterial>,icons:&mut Assets<crate::native_hud_icon_material::IconMaterial>) {
 for s in live.slots.drain(..) {commands.entity(s.sector).despawn();commands.entity(s.line).despawn();meshes.remove(s.mesh.id());sectors.remove(s.sector_material.id());lines.remove(s.line_material.id());}
 for e in [live.camera.take(),live.overlay.take()].into_iter().flatten() {commands.entity(e).despawn();}if let Some(h)=live.target.take() {images.remove(h.id());}if let Some(h)=live.overlay_material.take() {icons.remove(h.id());}live.signature=None;
}
fn hide(live:&Live,commands:&mut Commands) {for s in &live.slots {commands.entity(s.sector).insert(Visibility::Hidden);commands.entity(s.line).insert(Visibility::Hidden);}if let Some(e)=live.overlay {commands.entity(e).insert(Visibility::Hidden);}}
#[allow(clippy::too_many_arguments)]
fn update(mut commands:Commands,game:Res<crate::Match>,connection:Res<crate::Connection>,window:Query<&Window,With<PrimaryWindow>>,viewport:Res<crate::native_hud_viewport::Viewport>,mut images:ResMut<Assets<Image>>,mut meshes:ResMut<Assets<Mesh>>,mut sectors:ResMut<Assets<RechargeMaterial>>,mut lines:ResMut<Assets<LineMaterial>>,mut icons:ResMut<Assets<crate::native_hud_icon_material::IconMaterial>>,mut live:ResMut<Live>) {
 if live.sources.len()!=6 {return;}let Some(snapshot)=&game.snapshot else {hide(&live,&mut commands);return;};let Some(player)=snapshot.players.iter().find(|p|Some(p.id)==connection.id) else {hide(&live,&mut commands);return;};
 let params=match crate::native_hud_summoners::recharge(player,snapshot.tick) {Ok(v)=>v,Err(e)=>{hide(&live,&mut commands);if live.error.as_deref()!=Some(e) {eprintln!("Native recharge HUD unavailable: {e}");live.error=Some(e.into());}return;}};
 let Ok(window)=window.single() else{return;};let dimensions=[window.physical_width(),window.physical_height()];if dimensions.contains(&0) {hide(&live,&mut commands);return;}let dpi=window.scale_factor();let signature=format!("{dimensions:?}:{dpi}:{}",viewport.scalar.to_bits());
 if live.signature.as_ref()!=Some(&signature) {
  let payloads=live.sources.iter().map(|s| {let bounds=rect(s,dimensions,viewport.scalar)?;let vertices=crate::native_hud_recharge::geometry(bounds,dimensions,s.word(0x1dc)).map_err(str::to_owned)?;let uniforms=crate::native_hud_effect_uniforms::from_storage(s).map_err(str::to_owned)?;Ok((bounds,vertices,uniforms))}).collect::<Result<Vec<_>,String>>();let payloads=match payloads {Ok(v)=>v,Err(e)=>{hide(&live,&mut commands);eprintln!("Native recharge geometry unavailable: {e}");return;}};
  remove(&mut live,&mut commands,&mut images,&mut meshes,&mut sectors,&mut lines,&mut icons);
  let mut target=Image::new(Extent3d {width:dimensions[0],height:dimensions[1],depth_or_array_layers:1},TextureDimension::D2,vec![0;dimensions[0] as usize*dimensions[1] as usize*4],TextureFormat::Rgba8Unorm,RenderAssetUsages::MAIN_WORLD|RenderAssetUsages::RENDER_WORLD);target.texture_descriptor.usage=TextureUsages::RENDER_ATTACHMENT|TextureUsages::TEXTURE_BINDING|TextureUsages::COPY_SRC|TextureUsages::COPY_DST;target.sampler=bevy::image::ImageSampler::nearest();let target=images.add(target);
  live.camera=Some(commands.spawn((Camera2d,Camera {order:-1,clear_color:ClearColorConfig::Custom(Color::linear_rgba(0.,0.,0.,0.)),..default()},RenderTarget::Image(target.clone().into()),Tonemapping::None,Msaa::Off,RenderLayers::layer(31),Name::new("NativeRechargeLineCamera"))).id());
  let w=dimensions[0] as f32/dpi;let h=dimensions[1] as f32/dpi;
  for (slot,(bounds,vertices,u)) in payloads.into_iter().enumerate() {
   let sector_material=sectors.add(RechargeMaterial {parameters:Parameters {params:Vec4::ZERO,color0:Vec4::from_array(u.colors_rgba[0]),color1:Vec4::from_array(u.colors_rgba[1])}});
   let sector=commands.spawn((Node {position_type:PositionType::Absolute,left:Val::Px(bounds[0]*w),top:Val::Px(bounds[1]*h),width:Val::Px((bounds[2]-bounds[0])*w),height:Val::Px((bounds[3]-bounds[1])*h),..default()},MaterialNode(sector_material.clone()),Visibility::Hidden,GlobalZIndex(83),Name::new(format!("NativeRechargeSector{slot}")))).id();
   let mesh=meshes.add(native_hud_recharge_line::mesh(&vertices));let line_material=lines.add(LineMaterial {parameters:native_hud_recharge_line::Parameters {projection:native_hud_recharge_line::viewport_projection(),direction:Vec4::ZERO}});let line=commands.spawn((Mesh2d(mesh.clone()),MeshMaterial2d(line_material.clone()),Transform::default(),RenderLayers::layer(31),Visibility::Hidden,Name::new(format!("NativeRechargeLine{slot}")))).id();live.slots.push(Slot {sector,line,sector_material,line_material,mesh});
  }
  let overlay_material=icons.add(crate::native_hud_icon_material::IconMaterial {parameters:crate::native_hud_icon_material::Parameters {uv:Vec4::new(0.,0.,1.,1.),vertex_color:Vec4::ONE,tint:Vec4::ONE,mode:Vec4::new(3.,0.,0.,0.)},texture:target.clone()});
  live.overlay=Some(commands.spawn((Node {position_type:PositionType::Absolute,left:Val::Px(0.),top:Val::Px(0.),width:Val::Px(w),height:Val::Px(h),..default()},MaterialNode(overlay_material.clone()),GlobalZIndex(83),Visibility::Hidden,Name::new("NativeRechargeLineComposite"))).id());live.overlay_material=Some(overlay_material);live.target=Some(target);live.signature=Some(signature);
 }
 let mut records=Vec::new();for (slot,state) in live.slots.iter().enumerate() {let (cooldown_end,cooldown_total)=crate::native_hud_summoners::cooldown(player,slot).expect("validated current cooldown profile");let visible=params[slot].is_some();let visibility=if visible {Visibility::Visible}else {Visibility::Hidden};commands.entity(state.sector).insert(visibility);commands.entity(state.line).insert(visibility);
  let direction=params[slot].map(|p|crate::native_hud_recharge::direction(p.x).unwrap().1);if let Some(params)=params[slot] {sectors.get_mut(&state.sector_material).unwrap().parameters.params=params;lines.get_mut(&state.line_material).unwrap().parameters.direction=direction.unwrap();}
  records.push(serde_json::json!({"slot":slot,"active":visible,"params":params[slot].map(|p|p.to_array()),"direction":direction.map(|p|p.to_array()),"cooldown_end":cooldown_end,"cooldown_total":cooldown_total,"total_source":if slot<4 {"authoritative snapshot"}else {"current core unmodified base profile"},"rect":rect(&live.sources[slot],dimensions,viewport.scalar).unwrap()}));
 }
 if let Some(e)=live.overlay {commands.entity(e).insert(if params.iter().any(Option::is_some) {Visibility::Visible}else {Visibility::Hidden});}live.error=None;
 if let Ok(path)=std::env::var("OPENLEAGUE_NATIVE_HUD_RECHARGE_TRACE") {let report=serde_json::json!({"complete":false,"session":snapshot.session,"summoners":crate::native_hud_summoners::trace(player,snapshot.tick),"tick":snapshot.tick,"player":connection.id,"champion":player.champion,"viewport":dimensions,"dpi":dpi,"elements":records,"geometry":"source quad and indexed two-segment LineStrip","transport":"sector UI + full-viewport linear nearest line target composited after sectors at source layer3","limits":["Explicit normalized viewport projection; original matrix producer, gamma, D3D9 edge coverage and whole HUD framebuffer fidelity remain unqualified.","QWER totals from snapshot; five accepted summoner totals from current core base profiles only (Smite90 provisional, Heal240). Original server summoner totals, modifiers, ammo/recasts/forms remain open."]});if let Err(e)=std::fs::write(path,serde_json::to_vec_pretty(&report).unwrap()) {eprintln!("Native recharge trace failed: {e}");}}
}
#[cfg(test)] mod tests {
 use super::*;
 #[test] fn real_native_effects_align_with_icons_and_authoritative_cast_and_expiry() {
  let r=std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..");let mut provider=crate::native_zip_provider::Provider::from_catalog(&r).unwrap();let hud=provider.startup_hud(&r).unwrap();let sources=source(&hud).unwrap();assert_eq!(sources.len(),6);let factor=f32::from_bits(0x3b808081);for (slot,alpha) in [(4,100.0),(5,180.0)] {let u=crate::native_hud_effect_uniforms::from_storage(&sources[slot]).unwrap();assert_eq!(u.colors_rgba[1],[0.,0.,128.*factor,alpha*factor]);}
  for (slot,s) in sources.iter().enumerate() {let name=crate::native_hud_summoners::icon_name(slot);let icon=hud.shadow_isles_layouts.iter().flat_map(|l|l.structure.accepted.iter()).find(|r|r.element.storage.kind()==1 && r.element.storage.bytes()[..32].split(|b|*b==0).next().unwrap()==name.as_bytes()).unwrap();for dims in [[1280,800],[1920,1080]] {assert_eq!(rect(s,dims,1.).unwrap(),rect(&icon.element.storage,dims,1.).unwrap());}assert_eq!(s.word(0x1dc),0xff8080ff);}
  let nav=openleague_core::Navigation::load(&std::fs::read_to_string(r.join("assets/maps/tt_navigation_grid.json")).unwrap(),&std::fs::read(r.join("assets/maps/tt_navigation_grid.cells.bin")).unwrap()).unwrap();let mut sim=openleague_core::Simulation::new(nav).unwrap();let id=sim.join("annie").unwrap();assert_eq!(crate::native_hud_recharge::player_params(&sim.players[&id],0).unwrap(),[None;4]);sim.learn(id,2).unwrap();sim.cast(id,2,None).unwrap();let begin=crate::native_hud_recharge::player_params(&sim.players[&id],0).unwrap();assert!(begin[2].is_some());assert_eq!(begin.iter().filter(|v|v.is_some()).count(),1);assert_eq!(crate::native_hud_recharge::player_params(&sim.players[&id],300).unwrap(),[None;4]);
 }
}
